import{_ as i,o as a,c as t,a2 as n}from"./chunks/framework.Bqa2y7hU.js";const r=JSON.parse('{"title":"首次配置","description":"Xiaoyi_QQ_V4 首次配置的两条路径：Web 安装向导与手动编辑 config/bot.toml。","frontmatter":{"title":"首次配置","description":"Xiaoyi_QQ_V4 首次配置的两条路径：Web 安装向导与手动编辑 config/bot.toml。"},"headers":[],"relativePath":"deploy/config.md","filePath":"deploy/config.md","lastUpdated":1789447036000}'),e={name:"deploy/config.md"};function l(o,s,p,h,d,c){return a(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="首次配置-🔧" tabindex="-1">首次配置 🔧 <a class="header-anchor" href="#首次配置-🔧" aria-label="Permalink to &quot;首次配置 🔧&quot;">​</a></h1><p>装完程序后，你需要把数据库连上、把管理员账号建出来，服务才算真正可用。这页讲两条路径：<strong>Web 安装向导</strong>（推荐，适合绝大多数人）与<strong>手动编辑配置文件</strong>。读完你能独立完成首次配置，也知道装完怎么回到向导重来。</p><h2 id="_1-安装向导是怎么触发的" tabindex="-1">1. 安装向导是怎么触发的 <a class="header-anchor" href="#_1-安装向导是怎么触发的" aria-label="Permalink to &quot;1. 安装向导是怎么触发的&quot;">​</a></h2><p>程序启动时会检查<strong>当前目录下有没有 <code>.installed</code> 这个标记文件</strong>：</p><ul><li>没有 <code>.installed</code> → 进入 <strong>Web 安装向导</strong>模式，监听 <code>8080</code>；</li><li>有 <code>.installed</code> → 直接以正常模式启动，提供正式服务。</li></ul><p>所以首次安装后，打开浏览器访问 <code>http://&lt;你的服务器IP&gt;:8080/</code> 下的任意地址，都会自动跳转到安装向导页面：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://&lt;你的服务器IP&gt;:8080/install</span></span></code></pre></div><h2 id="_2-用-web-安装向导-推荐" tabindex="-1">2. 用 Web 安装向导（推荐） <a class="header-anchor" href="#_2-用-web-安装向导-推荐" aria-label="Permalink to &quot;2. 用 Web 安装向导（推荐）&quot;">​</a></h2><p>向导分两步填表，都是必填项。</p><p><strong>第一步：数据库连接信息</strong></p><p>按你的 PostgreSQL 实例填写：主机、端口、用户名、密码、数据库名。填写前请确认这个库已经存在，且账号有建表权限。</p><p><strong>第二步：管理员账号</strong></p><p>设置管理员用户名与密码，这就是你之后登录控制台的凭据。</p><p>提交后向导会在一次流程里做完下面这些事：</p><ol><li>用你给的信息连接数据库；</li><li><strong>自动建表并应用全部迁移</strong>（<code>migrations/*.sql</code>，运行时自动执行，不需要你手工导入）；</li><li>创建管理员账号；</li><li>给这个账号发放<strong>免费额度</strong>：1 个机器人位、5 个插件位；</li><li>生成 <code>config/bot.toml</code>，其中 <code>env = &quot;production&quot;</code>；</li><li>写入 <code>.installed</code> 标记，随即在同一进程里切换到正式服务模式。</li></ol><div class="tip custom-block"><p class="custom-block-title"><code>env = &quot;production&quot;</code> 的意义</p><p>向导写入的是 <code>production</code>。在这个取值下，找回密码等流程遵循生产安全策略，<strong>不会返回开发链接</strong>。以开发模式手工跑时才会看到开发链接，正式部署请保持 <code>production</code>。</p></div><details class="details custom-block"><summary>截图占位</summary><p>分别截两张图：向导第一步的数据库表单、第二步的管理员账号表单，便于以后补图说明每一项填什么。</p></details><h2 id="_3-手动编辑-config-bot-toml" tabindex="-1">3. 手动编辑 <code>config/bot.toml</code> <a class="header-anchor" href="#_3-手动编辑-config-bot-toml" aria-label="Permalink to &quot;3. 手动编辑 \`config/bot.toml\`&quot;">​</a></h2><p>不想用向导，也可以在启动前直接改配置文件。模板路径是 <code>config/bot.toml</code>（<code>.deb</code> 安装后位于 <code>/opt/xiaoyi_qq_c/config/bot.toml</code>）。</p><p>最关键的只有两处：数据库连接和运行环境。下面是一份最小示例：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">app</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;xbot&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">env  = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;production&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 正式部署保持 production；开发可写 development</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">database</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">host     = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;127.0.0.1&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # PostgreSQL 地址</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">port     = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5432</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # PostgreSQL 端口</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">user     = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;xiaoyi&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 数据库用户名</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">password = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # 数据库密码</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dbname   = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;xiaoyi&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 数据库名</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pool_size = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 连接池大小</span></span></code></pre></div><p>改完配置文件<strong>必须重启服务</strong>才生效：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xiaoyi-qq-c</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">不要写 <code>[[bot]]</code> 段</p><p>机器人实例<strong>不由配置文件管理</strong>，而是存在数据库里，在控制台「我的机器人」页面里增删改。老配置里的 <code>[[bot]]</code> 段已经废弃，写了不生效。</p><p>另外，本产品<strong>没有</strong>「用环境变量覆盖配置项」的机制，所有配置都写在 <code>config/bot.toml</code> 或控制台里。</p></div><p>完整的配置项说明见 <a href="/RuaBot.Doc/reference/config">配置项</a>。</p><h2 id="_4-忘记管理员密码-想重新安装" tabindex="-1">4. 忘记管理员密码 / 想重新安装 <a class="header-anchor" href="#_4-忘记管理员密码-想重新安装" aria-label="Permalink to &quot;4. 忘记管理员密码 / 想重新安装&quot;">​</a></h2><p>想回到安装向导重来（比如忘了管理员密码），按下面三步做：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1) 先停掉服务（必须先停，否则文件状态会被运行中的进程覆盖）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xiaoyi-qq-c</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2) 删掉安装标记</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/xiaoyi_qq_c/.installed</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3) 重新启动，服务会回到安装向导模式</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xiaoyi-qq-c</span></span></code></pre></div><p>之后重新访问 <code>http://&lt;你的服务器IP&gt;:8080/install</code> 即可。</p><div class="danger custom-block"><p class="custom-block-title">重新安装会重写配置文件</p><p>向导跑完会<strong>重新生成 <code>config/bot.toml</code></strong>，你之前手工改过的内容会被覆盖。操作前建议先备份一份：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/xiaoyi_qq_c/config/bot.toml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/xiaoyi_qq_c/config/bot.toml.bak</span></span></code></pre></div></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/RuaBot.Doc/reference/config">配置项</a></li><li><a href="/RuaBot.Doc/deploy/reverse-proxy">反向代理与 HTTPS</a></li><li><a href="/RuaBot.Doc/deploy/ops">备份与运维</a></li></ul>`,32)])])}const g=i(e,[["render",l]]);export{r as __pageData,g as default};
